import type { APIRoute } from 'astro';
import { getCollection, getEntry } from 'astro:content';
import { FEATURED_LIFE_CATEGORY_SLUGS, lifeCategoryLabels, postCategoryLabels } from '../config/categories';
import { siteConfig } from '../config/site';
import { friends } from '../data/friends';
import { getPostSlug, getPublishedPosts } from '../utils/posts';
import { markdownToText, type SearchEntry } from '../utils/search';

export const prerender = true;

// Generated by the existing Astro build; no separate indexing command or server.
export const GET: APIRoute = async () => {
  const [posts, life, about] = await Promise.all([
    getPublishedPosts(), getCollection('life'), getEntry('about', 'profile'),
  ]);

  const entries: SearchEntry[] = posts.map((post) => ({
    title: post.data.title,
    url: `/posts/${getPostSlug(post)}`,
    kind: '文章',
    description: post.data.description ?? '',
    tags: [...post.data.tags, ...(post.data.category ? [postCategoryLabels[post.data.category]] : [])],
    body: markdownToText(post.body),
  }));

  for (const item of life.sort((a, b) => b.data.date.getTime() - a.data.date.getTime())) {
    if (!FEATURED_LIFE_CATEGORY_SLUGS.some((category) => category === item.data.category)) continue;
    entries.push({
      title: item.data.title,
      url: `/life?category=${item.data.category}#${encodeURIComponent(`life-${item.slug}`)}`,
      kind: lifeCategoryLabels[item.data.category],
      description: item.data.description ?? '',
      tags: ['生活', lifeCategoryLabels[item.data.category]],
      // The life page displays metadata, not the Markdown body.
      body: '',
    });
  }

  if (about) entries.push({
    title: about.data.title, url: '/about', kind: '页面',
    description: about.data.description ?? '', tags: ['关于'], body: markdownToText(about.body),
  });

  for (const [i, friend] of friends.entries()) entries.push({
    title: friend.name, url: `/friends#friend-${i}`, kind: '友链',
    description: friend.description, tags: ['友链'], body: '',
  });

  entries.push(
    { title: siteConfig.name, url: '/', kind: '页面', description: siteConfig.description, tags: ['首页', '主页'], body: '' },
    { title: '文章归档', url: '/archive', kind: '页面', description: '按时间浏览全部已发布文章。', tags: ['归档'], body: '' },
    { title: '生活', url: '/life', kind: '页面', description: '音乐、摄影、游戏与番剧。', tags: ['生活'], body: '' },
    { title: '友链', url: '/friends', kind: '页面', description: '这里记录一些常看常逛的地方。', tags: ['友链'], body: '' },
  );

  return new Response(JSON.stringify(entries), {
    headers: { 'Content-Type': 'application/json; charset=utf-8' },
  });
};
